import {start,e,field,select,uid} from '../workshop-kit/ui.js?v=0.9.0';
import {model,LEVELS,markdown} from './state.js?v=0.9.0';
const name=step=>step.name.trim()||'Unnamed step';
function optionCard(item,work){return `<article class="intervention-chip ${work.selectedId===item.id?'selected':''}" data-drag-id="${e(item.id)}"><div><button class="option-title" data-act="inspect" data-id="${e(item.id)}">${e(item.title||'Name this intervention…')}</button><span class="anchor-label">↳ ${e(name(work.steps.find(step=>step.id===item.anchor)))}</span>${item.review?'<span class="review-tag">Recheck causal claim</span>':''}</div><button class="drag-handle" data-drag-handle data-act="move-menu" data-id="${e(item.id)}" aria-label="Move ${e(item.title||'intervention')}">⠿</button></article>`;}
function render(work){const item=work.options.find(item=>item.id===work.selectedId),anchor=item?work.steps.find(step=>step.id===item.anchor):null;return `<div class="section-top"><div><h2>Find the mechanism. Choose where to intervene.</h2><p>Keep each possible change beside the step it would affect.</p></div><span class="model-note">A causal hypothesis, not a proven chain.</span></div><section class="ladder-board"><div class="mechanism-rail"><div class="rail-heading"><span class="eyebrow">THE UNWANTED OUTCOME HAPPENS BECAUSE…</span><button class="text-button" data-act="add-step" ${work.steps.length>=7?'disabled':''}>+ Step</button></div>${work.steps.map((step,index)=>`<article class="mechanism-step ${anchor?.id===step.id?'active':''}"><div class="step-number">${index+1}</div><button data-act="edit-step" data-id="${e(step.id)}"><strong>${e(name(step))}</strong><span>${e(step.mechanism||'Describe how this step contributes.')}</span></button><div class="reorder"><button data-act="reorder" data-id="${e(step.id)}" data-dir="-1" aria-label="Move step ${index+1} earlier" ${index===0?'disabled':''}>↑</button><button data-act="reorder" data-id="${e(step.id)}" data-dir="1" aria-label="Move step ${index+1} later" ${index===work.steps.length-1?'disabled':''}>↓</button></div></article>${index<work.steps.length-1?'<div class="causal-arrow" aria-hidden="true">↓</div>':''}`).join('')}</div><div class="intervention-ladder"><div class="ladder-heading"><span class="eyebrow">SIX PLACES TO CHANGE THE MECHANISM</span><span>Drag an intervention to change its level.</span></div>${Object.entries(LEVELS).map(([key,level],index)=>`<section class="rung rung-${key}" data-drop-id="${key}" aria-label="${level.name} drop area"><div class="rung-label"><span>${String(index+1).padStart(2,'0')}</span><div><h3>${level.name}</h3><p>${level.verb}</p></div></div><div class="rung-options">${work.options.filter(item=>item.level===key).map(item=>optionCard(item,work)).join('')||'<span class="rung-empty">No idea at this level yet</span>'}</div><button class="rung-add" data-act="add-option" data-kind="${key}" aria-label="Add an intervention: ${level.name}" ${work.options.length>=24?'disabled':''}>+</button></section>`).join('')}<p class="ladder-note">Higher is not automatically better. Choose a level you can influence and a change whose effect you can test.</p></div></section>${item?`<section class="option-notebook" id="option-notebook"><div class="section-top"><div><span class="eyebrow">DEVELOP THIS INTERVENTION</span><h2>${e(item.title||'A possible change')}</h2><p><b>${LEVELS[item.level].name}</b> at “${e(name(anchor))}”</p></div><div class="notebook-actions"><button class="text-button" data-act="move-menu" data-id="${e(item.id)}">Change attachment</button><button class="text-button danger" data-act="remove" data-id="${e(item.id)}">Remove</button></div></div>${item.review?`<div class="review-notice">This intervention moved. Does its causal claim still fit the new place?<button class="text-button" data-act="reviewed" data-id="${e(item.id)}">I have checked it</button></div>`:''}<div class="option-fields">${field('option-title','Name the intervention',item.title,{type:'option',id:item.id,field:'title'})}${field('option-change','What changes in the mechanism?',item.change,{type:'option',id:item.id,field:'change'},LEVELS[item.level].prompt)}${field('option-why','Why should the outcome change?',item.why,{type:'option',id:item.id,field:'why'},'Name the link from this change to the unwanted outcome.')}${field('option-tradeoff','What does it cost or require?',item.tradeoff,{type:'option',id:item.id,field:'tradeoff'},'Include permissions, side effects, and work shifted elsewhere.')}</div><div class="choose-row"><p>Which intervention is worth taking into the world?</p><button class="button ${work.chosenId===item.id?'chosen':'primary'}" data-act="choose" data-id="${e(item.id)}">${work.chosenId===item.id?'✓ Chosen for a test':'Choose this intervention →'}</button></div>${work.chosenId===item.id?`<div class="test-panel"><h2>Make the causal claim earn its keep.</h2><div class="test-grid">${field('option-test','The smallest useful test',item.test,{type:'option',id:item.id,field:'test'},'Who does what, for how long, with which limit on effort?')}${field('option-evidence','What would change your mind?',item.evidence,{type:'option',id:item.id,field:'evidence'},'Which observation would make you stop, revise, or continue?')}</div></div>`:''}</section>`:'<div class="empty-note">Add an intervention at a level to develop it here.</div>'}`;}
function moveMenu(item,m){const work=m.work();m.open(`<p class="dialog-description">An intervention stays attached to a specific mechanism step.</p>${select('move-level','Intervention level',item.level,Object.entries(LEVELS).map(([key,value])=>[key,value.name]),{type:'move-option',id:item.id,anchor:item.anchor})}<div class="stack-options">${work.steps.map(step=>`<button data-act="attach" data-id="${e(item.id)}" data-key="${e(step.id)}"><strong>${e(name(step))}</strong><span>${e(step.mechanism||'Mechanism not written yet.')}</span></button>`).join('')}</div><p class="microcopy">Changing the attachment marks the causal claim for review. Your writing is retained.</p>`,'Attach this intervention');}
start({route:'interventions',number:'05',kicker:'CHANGE THE MECHANISM',title:'Intervention ladder',engine:model,examples:[['blank','+ My own problem'],['example','Product reviews'],['battery','Battery decisions']],workspaceSummary:work=>`${work.steps.length} steps · ${work.options.length} interventions`,markdown,render,drag:({itemId,dropId},m)=>{const item=m.work().options.find(item=>item.id===itemId);if(m.update({type:'move-option',id:itemId,level:dropId,anchor:item.anchor}))m.toast('Intervention moved. Check that its causal claim still fits.');},action:(data,m)=>{const work=m.work(),item=work.options.find(item=>item.id===data.id);if(data.act==='inspect'){m.update({type:'select',id:data.id},{checkpoint:false});m.scroll('option-notebook');}else if(data.act==='add-step'){const id=uid();if(m.update({type:'add-step',id}))editStep(work.steps.length,id,m);}else if(data.act==='edit-step')editStep(work.steps.findIndex(step=>step.id===data.id),data.id,m);else if(data.act==='reorder')m.update({type:'reorder-step',id:data.id,direction:Number(data.dir)});else if(data.act==='remove-step'){if(m.update({type:'remove-step',id:data.id}))m.close();}else if(data.act==='add-option'){m.open(`<p class="dialog-description">${LEVELS[data.kind].prompt}</p><div class="stack-options">${work.steps.map(step=>`<button data-act="create-option" data-kind="${data.kind}" data-key="${e(step.id)}"><strong>At: ${e(name(step))}</strong><span>${e(step.mechanism)}</span></button>`).join('')}</div>`,'Which step would this affect?');}else if(data.act==='create-option'){m.close();if(m.update({type:'add-option',id:uid(),anchor:data.key,level:data.kind},{focus:'option-title'}))m.scroll('option-notebook');}else if(data.act==='move-menu')moveMenu(item,m);else if(data.act==='attach'){const level=document.querySelector('#move-level').value;m.close();m.update({type:'move-option',id:data.id,level,anchor:data.key});}else if(data.act==='reviewed')m.update({type:'reviewed',id:data.id});else if(data.act==='remove'){if(m.update({type:'remove-option',id:data.id}))m.toast('Intervention removed. Undo restores it.');}else if(data.act==='choose'){m.update({type:'choose',id:data.id});m.toast('Chosen. Its test notes stay with this intervention.');}}});
function editStep(index,id,m){const step=m.work().steps.find(item=>item.id===id);m.open(`${field('step-name','What happens at this step?',step.name,{type:'step',id,field:'name'})}${field('step-mechanism','How does this contribute to the outcome?',step.mechanism,{type:'step',id,field:'mechanism'},'Describe a causal link, wait, or handoff rather than just a stage name.',3)}<div class="dialog-footer"><button class="text-button danger" data-act="remove-step" data-id="${e(id)}">Remove step</button><button class="button primary" data-act="@close">Done</button></div>`,'Edit the mechanism');}
